(7640400, 1240592, 80096, '<td valign="top">DNMC</td>', 'DNMC', '2019-09-04 01:20:31.000000', NULL, 1),
(7640412, 1240183, 67258, '<td valign="top">Very nice indeed, and perfect for the challenge.</td>', 'Very nice indeed, and perfect for the challenge.', '2019-09-04 05:15:17.000000', NULL, 1),
(7640413, 1240377, 67258, '<td valign="top">Excellent scene for the challenge.  The composition seems just a tad off - I wonder if you cropped in from the right if it would have more balance?</td>', 'Excellent scene for the challenge.  The composition seems just a tad off - I wonder if you cropped in from the right if it would have more balance?', '2019-09-04 05:16:24.000000', NULL, 1),
(7640414, 1240681, 67258, '<td valign="top">interesting scene, soundly composed.  There doesn''t seem to be any point where focus is sharp, though.</td>', 'interesting scene, soundly composed.  There doesn''t seem to be any point where focus is sharp, though.', '2019-09-04 05:17:20.000000', NULL, 1),
(7640415, 1240208, 67258, '<td valign="top">Well suited to the aspect ratio.  This is actually one of the few photos in the challenge where I forget the photo is an odd ratio - there is so much to see, my eyes dance all around the frame.  Good entry.</td>', 'Well suited to the aspect ratio.  This is actually one of the few photos in the challenge where I forget the photo is an odd ratio - there is so much to see, my eyes dance all around the frame.  Good entry.', '2019-09-04 05:19:06.000000', NULL, 1),
(7640417, 1240209, 114285, '<td valign="top">Oh so very pretty.</td>', 'Oh so very pretty.', '2019-09-04 05:38:51.000000', NULL, 1),
(7640418, 1240377, 114285, '<td valign="top">Great title! Love that sky, great landscape image, should do well.</td>', 'Great title! Love that sky, great landscape image, should do well.', '2019-09-04 05:39:40.000000', NULL, 1),
(7640440, 1240466, 67258, '<td valign="top">You will realise by now that you may have missed the point of the challenge - to explore different aspect ratios and to choose your composition to suit.  Here, whilst you have met the challenge in so much as one side is 240 px, the standard aspect ratio means you simply have a very small image.  It''s a sweet deer, though :)</td>', 'You will realise by now that you may have missed the point of the challenge - to explore different aspect ratios and to choose your composition to suit.  Here, whilst you have met the challenge in so much as one side is 240 px, the standard aspect ratio means you simply have a very small image.  It''s a sweet deer, though :)', '2019-09-04 09:25:08.000000', NULL, 1),
(7640452, 1240555, 42495, '<td valign="top">Cool, but I think this missed the intent of the challenge.</td>', 'Cool, but I think this missed the intent of the challenge.', '2019-09-04 11:45:56.000000', NULL, 1),
(7640456, 1240645, 67258, '<td valign="top">Woah, I feel quite vertiginous looking at this.  Excellent and totally surprising  entry!  Bumping to 10.  My choice for Blue.</td>', 'Woah, I feel quite vertiginous looking at this.  Excellent and totally surprising  entry!  Bumping to 10.  My choice for Blue.', '2019-09-04 12:23:21.000000', NULL, 1),
(7640458, 1240645, 123833, '<td valign="top">Really good, my highest score in this challenge</td>', 'Really good, my highest score in this challenge', '2019-09-04 12:33:08.000000', NULL, 1),
(7640459, 1240623, 123833, '<td valign="top">Very cute and great composition</td>', 'Very cute and great composition', '2019-09-04 12:34:29.000000', NULL, 1),
(7640468, 1240652, 5628, '<td valign="top">Very Nice! My favourite shot in this challenge!</td>', 'Very Nice! My favourite shot in this challenge!', '2019-09-04 13:50:32.000000', NULL, 1),
(7640469, 1240635, 5628, '<td valign="top">Nice idea. The focus on the deer is a little soft, otherwise I would have scored this higher. Still a 7 though.</td>', 'Nice idea. The focus on the deer is a little soft, otherwise I would have scored this higher. Still a 7 though.', '2019-09-04 13:51:41.000000', NULL, 1),
(7640470, 1240191, 5628, '<td valign="top">Very nice! One of the best shots in the challenge.</td>', 'Very nice! One of the best shots in the challenge.', '2019-09-04 13:52:05.000000', NULL, 1),
(7640478, 1240514, 67258, '<td valign="top">I do like this!  Brooding and dark.  The composition suits the aspect ratio well.  Bumping to 8.</td>', 'I do like this!  Brooding and dark.  The composition suits the aspect ratio well.  Bumping to 8.', '2019-09-04 15:24:25.000000', NULL, 1),
